import postcss from 'postcss';
const CUSTOM_PROPERTY_PATTERN = /^--[a-zA-Z0-9_-]+$/;
const HYPHEN_PATTERN = /-([a-z])/g;
const MS_VENDOR_PREFIX_PATTERN = /^-ms-/;
const toReactStyleProperty = (property) => {
    if (CUSTOM_PROPERTY_PATTERN.test(property))
        return property;
    if (!property.includes('-'))
        return property.toLowerCase();
    return property
        .toLowerCase()
        .replace(MS_VENDOR_PREFIX_PATTERN, 'ms-')
        .replace(HYPHEN_PATTERN, (_match, character) => character.toUpperCase());
};
/**
 * Converts an HTML style attribute into the object shape required by React.
 * Invalid declaration lists are treated as empty so authored HTML cannot crash rendering.
 */
export const parseInlineStyle = (style) => {
    try {
        const parsed = {};
        for (const declaration of postcss.parse(style, { from: undefined }).nodes) {
            if (declaration.type !== 'decl' || !declaration.value)
                continue;
            // PostCSS stores priority separately because React style objects only accept the value.
            parsed[toReactStyleProperty(declaration.prop)] = declaration.value;
        }
        return parsed;
    }
    catch (_a) {
        return {};
    }
};
